module tb;
    // Declare inputs as regs, outputs as wires
    reg clk;
    reg load;
    reg [1:0] ena;
    reg [99:0] data;
    wire [99:0] q;

    // Instantiate TopModule
    TopModule dut (
        .clk(clk),
        .load(load),
        .ena(ena),
        .data(data),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    reg [99:0] expected_q;

    initial begin
        // Initialize signals
        clk = 0;
        load = 0;
        ena = 2'b00;
        data = 100'h0;
        expected_q = 100'h0;

        #12; // Wait past first clock edge

        // Test 1: Load initial data
        load = 1'b1;
        ena = 2'b00;
        data = 100'h1; // LSB set
        expected_q = 100'h1;
        @(posedge clk);
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Turn off load
        load = 1'b0;

        // Test 2: Rotate Left (2'b10)
        // 100'h1 rotated left by 1 becomes 100'h2
        ena = 2'b10;
        expected_q = {expected_q[98:0], expected_q[99]};
        @(posedge clk);
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Test 3: Hold state (2'b00)
        ena = 2'b00;
        @(posedge clk);
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Test 4: Rotate Right (2'b01)
        ena = 2'b01;
        expected_q = {expected_q[0], expected_q[99:1]};
        @(posedge clk);
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Test 5: Hold state (2'b11)
        ena = 2'b11;
        @(posedge clk);
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Test 6: Multiple continuous left rotations with a complex pattern
        load = 1'b1;
        data = 100'h3F0A_55AA_FF00_1234_5678_9ABC_DEF0;
        expected_q = data;
        @(posedge clk);
        #1;
        load = 1'b0;
        ena = 2'b10;

        repeat (10) begin
            expected_q = {expected_q[98:0], expected_q[99]};
            @(posedge clk);
            #1;
            if (q !== expected_q) errors = errors + 1;
        end

        // Test 7: Multiple continuous right rotations
        ena = 2'b01;
        repeat (10) begin
            expected_q = {expected_q[0], expected_q[99:1]};
            @(posedge clk);
            #1;
            if (q !== expected_q) errors = errors + 1;
        end

        // Final result check
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
